#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/uio.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <file> <offset> <data>\n", argv[0]);
        return 1;
    }

    const char *file = argv[1];
    unsigned long offset = strtoul(argv[2], NULL, 0);
    const char *data = argv[3];

    int fd = open(file, O_RDONLY | O_CLOEXEC);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    unsigned long pipes[2];
    if (pipe((int *)pipes) < 0) {
        perror("pipe");
        return 1;
    }

    unsigned long n = strlen(data);
    splice(fd, &offset, pipes[1], NULL, n, 0);

    ssize_t ret = write(pipes[1], data, n);
    if (ret < 0) {
        perror("write");
    }

    splice(pipes[0], NULL, fd, &offset, n, SPLICE_F_MOVE);

    close(fd);
    close(pipes[0]);
    close(pipes[1]);
    return 0;
}
EOF
