static void to_hex(const unsigned char *b, size_t n, char *out) {
    static const char *h = "0123456789abcdef";
    for (size_t i = 0; i < n; i++) {
        out[2*i]     = h[(b[i] >> 4) & 0xf];
        out[2*i + 1] = h[b[i] & 0xf];
    }
    out[2*n] = '\0';
}

