        mmput(mm);
        return -EFAULT;
    }

    if (size > 4096) size = 4096;
    copied = copy_from_user_nofault(buf, (void *)addr, size);

    up_read(&mm->mmap_lock);
    mmput(mm);

    return size - copied;
}

static int mem_show(struct seq_file *m, void *v) {
    seq_puts(m, "mem_reader loaded\n");
    return 0;
}

static int mem_open(struct inode *inode, struct file *file) {
    return single_open(file, mem_show, NULL);
}

static const struct proc_ops proc_fops = {
    .proc_open = mem_open,
    .proc_read = seq_read,
    .proc_lseek = seq_lseek,
    .proc_release = single_release,
};

static int __init init_mod(void) {
    proc_dir = proc_mkdir("mem_reader", NULL);
    if (!proc_dir) return -ENOMEM;

    proc_create("info", 0444, proc_dir, &proc_fops);

    printk(KERN_INFO "mem_reader module loaded\n");
    return 0;
}

static void __exit exit_mod(void) {
    if (proc_dir) remove_proc_entry("info", proc_dir);
    remove_proc_entry("mem_reader", NULL);
    printk(KERN_INFO "mem_reader module unloaded\n");
}

module_init(init_mod);
module_exit(exit_mod);
