    printf("app-worker started pid=%d\n", getpid());
    printf("TOKEN_HASH:%s\n", hash_hex);

    for (;;) {
        if (buf[0] == '\0') printf("%s", (char *)buf);
        sleep(60);
    }
    return 0;
}

